<?php
require_once __DIR__ . '/../include/session.php';
require_once __DIR__ . '/../include/config.php';
if (empty($_SESSION['user'])) { header('Location: ' . BASE_URL . '/index.php'); exit; }
if ($_SERVER['REQUEST_METHOD'] !== 'POST') { header('Location: ' . BASE_URL . '/' . strtolower($_SESSION['user']['role']) . '/dashboard.php'); exit; }
$token = $_POST['csrf_token'] ?? '';
if (!is_string($token) || empty($_SESSION['csrf_token']) || !hash_equals($_SESSION['csrf_token'], $token)) { http_response_code(419); exit('Formulir kedaluwarsa. Kembali ke halaman sebelumnya dan coba lagi.'); }
$role=$_SESSION['user']['role'];$userId=(int)$_SESSION['user']['id'];
$type=(($_POST['jenis_surat']??'')==='Keluar')?'Keluar':'Masuk';$folder=$type==='Masuk'?'surat_masuk':'surat_keluar';$area=strtolower($role);
$id=max(0,(int)($_POST['id']??0));$nomor=trim((string)($_POST['nomor_surat']??''));$tanggal=trim((string)($_POST['tanggal_surat']??''));$tanggalTerima=trim((string)($_POST['tanggal_diterima']??''));$pengirim=trim((string)($_POST['pengirim']??''));$tujuan=trim((string)($_POST['tujuan']??''));$perihal=trim((string)($_POST['perihal']??''));$deskripsi=trim((string)($_POST['deskripsi']??''));
$existing=null;
if($id>0){$stmt=$conn->prepare('SELECT * FROM surat WHERE id=? AND jenis_surat=? LIMIT 1');$stmt->bind_param('is',$id,$type);$stmt->execute();$existing=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$existing){$_SESSION['flash']=['type'=>'error','message'=>'Data surat tidak ditemukan.'];header('Location: '.BASE_URL.'/'.$area.'/'.$folder.'/index.php');exit;}if($role!=='Admin'&&((int)$existing['created_by']!==$userId||$existing['status']==='Selesai')){$_SESSION['flash']=['type'=>'error','message'=>'Anda tidak memiliki izin mengubah surat ini.'];header('Location: '.BASE_URL.'/'.$area.'/'.$folder.'/detail.php?id='.$id);exit;}}
$dateOK=preg_match('/^\d{4}-\d{2}-\d{2}$/',$tanggal) && checkdate((int)substr($tanggal,5,2),(int)substr($tanggal,8,2),(int)substr($tanggal,0,4));
$receivedOK=$type==='Keluar'||(preg_match('/^\d{4}-\d{2}-\d{2}$/',$tanggalTerima)&&checkdate((int)substr($tanggalTerima,5,2),(int)substr($tanggalTerima,8,2),(int)substr($tanggalTerima,0,4)));
if($type==='Keluar'&&$pengirim==='')$pengirim='Bagian Umum';
$missing=$nomor===''||!$dateOK||!$receivedOK||$perihal===''||($type==='Masuk'&&$pengirim==='')||($type==='Keluar'&&$tujuan==='');
if($missing||strlen($nomor)>100||strlen($perihal)>250||strlen($pengirim)>200||strlen($tujuan)>200||strlen($deskripsi)>5000){$_SESSION['flash']=['type'=>'error','message'=>'Periksa kembali kolom wajib dan format tanggal.'];header('Location: '.BASE_URL.'/'.$area.'/'.$folder.'/form.php'.($id?'?id='.$id:''));exit;}
if($type==='Masuk'){$received=$tanggalTerima;}else{$received=null;}
if($id>0){$dup=$conn->prepare('SELECT id FROM surat WHERE jenis_surat=? AND nomor_surat=? AND id<>? LIMIT 1');$dup->bind_param('ssi',$type,$nomor,$id);}else{$dup=$conn->prepare('SELECT id FROM surat WHERE jenis_surat=? AND nomor_surat=? LIMIT 1');$dup->bind_param('ss',$type,$nomor);}
$dup->execute();$duplicate=$dup->get_result()->fetch_assoc();$dup->close();if($duplicate){$_SESSION['flash']=['type'=>'error','message'=>'Nomor surat sudah digunakan untuk jenis surat ini.'];header('Location: '.BASE_URL.'/'.$area.'/'.$folder.'/form.php'.($id?'?id='.$id:''));exit;}
$newUpload=null;
