$uploadedFile=$newUpload?:($existing['uploaded_file']??null);
try{
 if($id>0){$stmt=$conn->prepare('UPDATE surat SET nomor_surat=?,tanggal_surat=?,tanggal_diterima=?,pengirim=?,tujuan=?,perihal=?,deskripsi=?,uploaded_file=?,updated_by=? WHERE id=?');$stmt->bind_param('ssssssssii',$nomor,$tanggal,$received,$pengirim,$tujuan,$perihal,$deskripsi,$uploadedFile,$userId,$id);$stmt->execute();$stmt->close();if($newUpload&&!empty($existing['uploaded_file'])){$oldPath=__DIR__.'/../uploads/surat/'.basename($existing['uploaded_file']);if(is_file($oldPath))unlink($oldPath);}$_SESSION['flash']=['type'=>'success','message'=>'Data surat berhasil diperbarui.'];header('Location: '.BASE_URL.'/'.$area.'/'.$folder.'/detail.php?id='.$id);exit;}
 $initialStatus=$type==='Masuk'?'Diterima':'Draft';$conn->begin_transaction();$stmt=$conn->prepare('INSERT INTO surat (jenis_surat,nomor_surat,tanggal_surat,tanggal_diterima,pengirim,tujuan,perihal,deskripsi,uploaded_file,status,created_by,updated_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->bind_param('ssssssssssii',$type,$nomor,$tanggal,$received,$pengirim,$tujuan,$perihal,$deskripsi,$uploadedFile,$initialStatus,$userId,$userId);$stmt->execute();$newId=(int)$conn->insert_id;$stmt->close();$catatan='Surat dicatat ke dalam sistem.';$log=$conn->prepare('INSERT INTO surat_status_logs (surat_id,status_lama,status_baru,catatan,changed_by) VALUES (?,NULL,?,?,?)');$log->bind_param('issi',$newId,$initialStatus,$catatan,$userId);$log->execute();$log->close();$conn->commit();$_SESSION['flash']=['type'=>'success','message'=>'Surat berhasil dicatat dengan status awal '.$initialStatus.'.'];header('Location: '.BASE_URL.'/'.$area.'/'.$folder.'/detail.php?id='.$newId);exit;
}catch(Throwable $error){if($conn->errno){try{$conn->rollback();}catch(Throwable $ignored){}}if($newUpload){$filePath=__DIR__.'/../uploads/surat/'.basename($newUpload);if(is_file($filePath))unlink($filePath);}$_SESSION['flash']=['type'=>'error','message'=>'Surat gagal disimpan. Pastikan nomor surat belum digunakan dan database dapat diakses.'];header('Location: '.BASE_URL.'/'.$area.'/'.$folder.'/form.php'.($id?'?id='.$id:''));exit;}
